import {readFileSync,writeFileSync,existsSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {spawn} from 'node:child_process';
const root='/Users/ilyagulya/Projects/My/bend',dir='/private/tmp/bend-g33-diagnostics-gSUmym';
const json=path=>JSON.parse(readFileSync(path,'utf8'));
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
const hash=path=>sha(readFileSync(path));
const manifest=json(dir+'/manifest.json'),planPath=root+'/evals/receipts/producer2039g33_stage_plan.json';
const fresh=(path,bytes)=>{if(existsSync(path)){if(hash(path)!==sha(bytes))throw Error('Existing generated file differs: '+path);}else writeFileSync(path,bytes,{flag:'wx'});};
if(process.argv[2]==='--run'){
 const plan=json(planPath);
 for(const command of plan.commands){
  await new Promise((resolve,reject)=>{const child=spawn(command[0],command.slice(1),{cwd:root,stdio:'inherit',env:{...process.env,HEAVY_GATE_MEMORY_MIB:'8192',HEAVY_GATE_RSS_MIB:'8192',HEAVY_GATE_POLL_MS:'10',HEAVY_GATE_TIMEOUT_MS:'600000',BUN_JSC_forceRAMSize:'4294967296'}});child.once('error',reject);child.once('exit',(code,signal)=>code===0?resolve():reject(Error('Diagnostic failed: '+code+' '+signal)));});
 }
}else{
 const specs={control:[['backend-enter',8,'emit_linked'],['source-assembly-enter',8,'program_source'],['scalar-pass-enter',8,'js_scalar_program']],candidate:[['optimizer-enter',2,'optimize'],['backend-enter',9,'emit_linked'],['source-assembly-enter',9,'program_source'],['width-analysis-enter',2,'result_widths'],['scalar-pass-enter',9,'js_scalar_program']]};
 const images={};
 for(const role of ['control','candidate']){
  const input=manifest.roles[role].image;if(hash(input.path)!==input.sha256)throw Error('Original image drift');
  let source=readFileSync(input.path,'utf8'),instrumented=source;
  const attribution=json(dir+'/'+role+'-emit.result.json.attribution.json').map,sites=[];
  for(const [label,provider,fn]of specs[role]){
   const key='emitter_steps_v1.emitter_body_cps_provider_'+provider+'_'+fn;
   const entries=Object.entries(attribution).filter(([,value])=>value===key);if(entries.length!==1)throw Error('Marker key cardinality '+key);
   const id=entries[0][0],pattern=new RegExp('function \\'+id+'\\([^)]*\\)\\{','g'),matches=[...source.matchAll(pattern)];if(matches.length!==1)throw Error('Function cardinality '+id);
   const opener=matches[0][0],insertion='$g33StageMark('+JSON.stringify(label)+');';instrumented=instrumented.replace(opener,opener+insertion);sites.push({label,key,code:id,offset:matches[0].index+opener.length,insertion});
  }
  const prelude='const $g33StageMark = globalThis.__g33StageMark;\n';instrumented=prelude+instrumented;
  let restored=instrumented.slice(prelude.length);for(const site of sites)restored=restored.replace(site.insertion,'');if(restored!==source)throw Error('Original byte preservation failed');
  const path=dir+'/'+role+'-stage-marked.mjs';fresh(path,instrumented);
  images[role]={original:input,instrumented:{path,sha256:hash(path),bytes:Buffer.byteLength(instrumented)},prelude,insertions:sites,exactOriginalReconstruction:true};
  fresh(dir+'/'+role+'-stage-transform.json',JSON.stringify(images[role],null,2)+'\n');
 }
 let driver=readFileSync(root+'/evals/selfhost_throughput.mjs','utf8');
 for(const file of ['heavy_gate.ts','native_seed_runtime.mjs','checker_core_step_runtime.mjs'])driver=driver.replace("'./"+file+"'",JSON.stringify(root+'/evals/'+file));
 const replacements=[
  ['const script=fileURLToPath(import.meta.url);',"const G33_STAGE_EVENTS=[];globalThis.__g33StageMark=stage=>G33_STAGE_EVENTS.push({stage,elapsedMs:performance.now(),cpu:process.cpuUsage()});\nconst script=fileURLToPath(import.meta.url);"],
  ['const before=performance.now(),cpu=process.cpuUsage();report.activePhase=name;save(reportPath,report);',"const before=performance.now(),cpu=process.cpuUsage();if(name==='emit')globalThis.__g33StageMark('emit-start');report.activePhase=name;save(reportPath,report);"],
  ['const result=await action(),used=process.cpuUsage(cpu);',"const result=await action();if(name==='emit')globalThis.__g33StageMark('emit-success');const used=process.cpuUsage(cpu);"],
  ['(await import(pathToFileURL(request.image).href)).default','(await import(pathToFileURL(request.stageImage.path).href)).default'],
  ['report.pipelineElapsedMs=performance.now()-started;','report.stageEvents=G33_STAGE_EVENTS;report.instrumentation=request.instrumentation;report.pipelineElapsedMs=performance.now()-started;']
 ];
 for(const [before,after]of replacements){if(driver.split(before).length!==2)throw Error('Driver anchor '+before);driver=driver.replace(before,after);}
 const driverPath=dir+'/stage-markers.mjs';fresh(driverPath,driver);
 const guard=[manifest.tools.bun,'--smol','evals/heavy_gate.ts','--memory-mib','8192','--rss-mib','8192','--poll-ms','10','--timeout-ms','600000','--'],commands=[];
 for(const role of ['control','candidate']){
  const request=json(dir+'/'+role+'-check.request.json');request.stageImage=images[role].instrumented;request.instrumentation=images[role];request.pins[request.stageImage.path]=request.stageImage.sha256;request.pins[driverPath]=hash(driverPath);
  const path=dir+'/'+role+'-stage.request.json';fresh(path,JSON.stringify(request,null,2)+'\n');
  commands.push([...guard,manifest.tools.node,'--experimental-strip-types','--max-old-space-size=6144','--max-semi-space-size=128',driverPath,'--worker','js',path,hash(path),dir+'/'+role+'-stage.result.json']);
 }
 const plan={schemaVersion:1,status:'PREDECLARED_COMPLETE_CPS_PHASE_INTERVALS',diagnosticOnly:true,compilerAccepted:false,performanceAccepted:false,limits:manifest.limits,worker:manifest.worker,environment:{HEAVY_GATE_MEMORY_MIB:8192,HEAVY_GATE_RSS_MIB:8192,HEAVY_GATE_POLL_MS:10,HEAVY_GATE_TIMEOUT_MS:600000,BUN_JSC_forceRAMSize:4294967296},commands,driver:{path:driverPath,sha256:hash(driverPath)},preparation:{path:process.argv[1],sha256:hash(process.argv[1])},images,boundaries:['emit-start to optimizer-enter: BIR/catalog construction (control continues to backend-enter because no optimizer exists).','optimizer-enter to backend-enter: complete transport CPS work including lower-result handoff, not synchronous entry-function return.','backend-enter to source-assembly-enter: JS linking, width validation and effect preparation.','source-assembly-enter to emit-success: source assembly including scalar preparation; scalar-pass-enter is an additional landmark, not an end marker.'],limitations:['Diagnostic copies only; original expected output SHA is required.','Markers observe actual runtime entry of the selected CPS source-body functions.','Wall intervals include scheduler/runtime and JIT/GC; process.cpuUsage covers all process threads.','Only a handful of marker entry hooks; no per-step timestamps.','No speedup or memory acceptance follows from these timings.']};
 fresh(planPath,JSON.stringify(plan,null,2)+'\n');console.log(JSON.stringify({status:plan.status,images,commands}));
}
